// Bible Studies data — four curated studies for different entry points

import 'package:flutter/material.dart';

class BibleStudy {
  final String id;
  final String title;
  final String subtitle;
  final String description;
  final IconData iconData;
  final int totalDays;
  final List<StudyDay> days;

  const BibleStudy({
    required this.id,
    required this.title,
    required this.subtitle,
    required this.description,
    required this.iconData,
    required this.totalDays,
    required this.days,
  });
}

class StudyDay {
  final int day;
  final String title;
  final String passage;
  final String passageText;
  final String reflection;
  final String aiPrompt;

  const StudyDay({
    required this.day,
    required this.title,
    required this.passage,
    required this.passageText,
    required this.reflection,
    required this.aiPrompt,
  });
}

// ── Studies ───────────────────────────────────────────────────────────────────

const List<BibleStudy> kBibleStudies = [

  // ── 1. Gospel of John ────────────────────────────────────────────────────
  BibleStudy(
    id: 'john_30',
    title: 'Gospel of John',
    subtitle: '30 Days',
    description: 'Walk through the most personal of the four gospels. John writes so that you may believe — and that through believing, you may have life.',
    iconData: Icons.menu_book,
    totalDays: 30,
    days: [
      StudyDay(day: 1, title: 'In the Beginning', passage: 'John 1:1-18', passageText: 'In the beginning was the Word, and the Word was with God, and the Word was God.', reflection: 'John opens not with a birth story but with eternity. What does it mean to you that God became flesh and "dwelt among us"?', aiPrompt: 'I\'m studying John 1:1-18 today — the prologue to John\'s gospel. Can you help me understand what John means by "the Word" (Logos), why he opens this way, and what it means that the Word became flesh and dwelt among us?'),
      StudyDay(day: 2, title: 'The First Disciples', passage: 'John 1:19-51', passageText: '"Come and see," they said.', reflection: 'Jesus\'s first invitation to his disciples was simply "come and see." What would it look like to respond to that same invitation today?', aiPrompt: 'I\'m reading John 1:19-51, where John the Baptist points to Jesus and the first disciples follow. Help me understand the significance of John saying "Behold, the Lamb of God" and what it meant for Andrew, Peter, Philip and Nathanael to follow Jesus.'),
      StudyDay(day: 3, title: 'Water into Wine', passage: 'John 2:1-12', passageText: 'This, the first of his signs, Jesus did at Cana in Galilee, and manifested his glory.', reflection: 'Jesus performed his first miracle at a wedding — an ordinary celebration. What does that tell you about where God shows up?', aiPrompt: 'I\'m studying the wedding at Cana in John 2:1-12. Help me understand why this was Jesus\'s first sign, what Mary\'s role reveals, and what it means that Jesus "manifested his glory" through something as ordinary as wine.'),
      StudyDay(day: 4, title: 'Cleansing the Temple', passage: 'John 2:13-25', passageText: '"Destroy this temple, and in three days I will raise it up."', reflection: 'Jesus showed righteous anger at what had corrupted worship. Is there anything that has replaced genuine worship in your own life?', aiPrompt: 'Help me understand Jesus cleansing the temple in John 2:13-25. Why was he so angry? What did the temple represent, and what did he mean when he said "destroy this temple and in three days I will raise it up"?'),
      StudyDay(day: 5, title: 'Born Again', passage: 'John 3:1-21', passageText: '"For God so loved the world, that he gave his only Son, that whoever believes in him should not perish but have eternal life."', reflection: 'Nicodemus came to Jesus at night — perhaps ashamed or afraid. Jesus met him with grace. Have you ever approached God in the dark?', aiPrompt: 'I\'m reading John 3:1-21, Jesus\'s conversation with Nicodemus. Help me understand what "born again" or "born of the Spirit" means, why Nicodemus struggled with it, and the full meaning of John 3:16 in its original context.'),
      StudyDay(day: 6, title: 'The Woman at the Well', passage: 'John 4:1-42', passageText: '"The water that I will give him will become in him a spring of water welling up to eternal life."', reflection: 'Jesus crossed every social barrier to reach this woman. Who are the people in your life that feel "too far" from God?', aiPrompt: 'Help me understand John 4:1-42 — Jesus and the Samaritan woman. Why was this encounter so shocking culturally? What did Jesus mean by "living water"? And why did this woman become one of the first evangelists in John\'s gospel?'),
      StudyDay(day: 7, title: 'I Am the Bread of Life', passage: 'John 6:25-59', passageText: '"I am the bread of life; whoever comes to me shall not hunger, and whoever believes in me shall never thirst."', reflection: 'The crowd wanted bread that filled their stomachs. Jesus offered something far deeper. What are you hungry for that only he can satisfy?', aiPrompt: 'I\'m studying John 6:25-59, the Bread of Life discourse. Help me understand what Jesus meant by calling himself "the bread of life," why the crowd was offended, and how this connects to the Exodus and manna in the wilderness.'),
      StudyDay(day: 8, title: 'Rivers of Living Water', passage: 'John 7:37-52', passageText: '"If anyone thirsts, let him come to me and drink."', reflection: 'Jesus stood up and cried out — an urgent, public invitation. He is still calling. What is keeping you from responding?', aiPrompt: 'Help me understand John 7:37-39, where Jesus cries out about living water at the Feast of Tabernacles. What was the significance of this feast, and what did Jesus mean about rivers of living water flowing from within?'),
      StudyDay(day: 9, title: 'I Am the Light', passage: 'John 8:12-30', passageText: '"I am the light of the world. Whoever follows me will not walk in darkness, but will have the light of life."', reflection: 'Darkness hides what we are ashamed of. Light reveals — but also heals. What are you afraid the light might expose in your own life?', aiPrompt: 'I\'m reading John 8:12-30. Help me understand what Jesus meant by "I am the light of the world," the significance of this claim in the context of the temple treasury, and why the Pharisees challenged him.'),
      StudyDay(day: 10, title: 'The Truth Will Set You Free', passage: 'John 8:31-59', passageText: '"If you abide in my word, you are truly my disciples, and you will know the truth, and the truth will set you free."', reflection: 'The Jews thought freedom meant political liberation. Jesus meant something far deeper. What does freedom in Christ look like for you personally?', aiPrompt: 'Help me unpack John 8:31-59. What did Jesus mean that "the truth will set you free"? Why did the religious leaders react so strongly? And what was Jesus claiming when he said "before Abraham was, I am"?'),
      StudyDay(day: 11, title: 'The Good Shepherd', passage: 'John 10:1-21', passageText: '"I am the good shepherd. The good shepherd lays down his life for the sheep."', reflection: 'A shepherd in the ancient world knew each sheep by name. Jesus knows your name. How does that change how you see yourself?', aiPrompt: 'I\'m studying John 10:1-21, the Good Shepherd passage. Help me understand the shepherd imagery in its cultural context, what it meant for Jesus to say he "lays down his life for the sheep," and the contrast with the hired hand.'),
      StudyDay(day: 12, title: 'I Am the Resurrection', passage: 'John 11:1-44', passageText: '"I am the resurrection and the life. Whoever believes in me, though he die, yet shall he live."', reflection: 'Jesus wept at the tomb of Lazarus — even knowing he was about to raise him. He enters into our grief. Have you let him into yours?', aiPrompt: 'Help me understand the raising of Lazarus in John 11:1-44. Why did Jesus wait? What did he mean by "I am the resurrection and the life"? And what is the significance of "Jesus wept" — the shortest verse in the Bible?'),
      StudyDay(day: 13, title: 'The Triumphal Entry', passage: 'John 12:12-36', passageText: '"Now is my soul troubled. And what shall I say? Father, save me from this hour? But for this purpose I have come to this hour."', reflection: 'The crowd celebrated Jesus as a king while misunderstanding his kingdom. How do we sometimes celebrate Jesus on our own terms rather than his?', aiPrompt: 'I\'m reading John 12:12-36. Help me understand the triumphal entry — what the crowd expected, what Jesus was actually doing, and what he meant about a grain of wheat falling to the earth to bear much fruit.'),
      StudyDay(day: 14, title: 'The Servant King', passage: 'John 13:1-20', passageText: '"If I then, your Lord and Teacher, have washed your feet, you also ought to wash one another\'s feet."', reflection: 'Foot washing was the work of the lowest servant. Jesus took that role willingly. What is the "foot washing" God might be calling you to do for someone in your life?', aiPrompt: 'Help me understand Jesus washing the disciples\' feet in John 13:1-20. What was the cultural significance of this act? Why did Peter resist? And what was Jesus teaching about greatness and service?'),
      StudyDay(day: 15, title: 'Do Not Let Your Hearts Be Troubled', passage: 'John 14:1-14', passageText: '"Let not your hearts be troubled. Believe in God; believe also in me."', reflection: 'Jesus spoke these words hours before his arrest. He offered peace in the middle of chaos. What is troubling your heart today?', aiPrompt: 'I\'m studying John 14:1-14. Help me understand what Jesus meant by "in my Father\'s house are many rooms," his claim to be "the way, the truth, and the life," and what it means that we will do "greater works" than he did.'),
      StudyDay(day: 16, title: 'The Holy Spirit', passage: 'John 14:15-31', passageText: '"The Helper, the Holy Spirit, whom the Father will send in my name, he will teach you all things."', reflection: 'Jesus promised not to leave his followers as orphans. The Spirit is present with you right now. How aware are you of his presence in your daily life?', aiPrompt: 'Help me understand Jesus\'s promises about the Holy Spirit in John 14:15-31. What does "Paraclete" or "Helper" mean in Greek? What does the Spirit do, and how do we experience his presence today?'),
      StudyDay(day: 17, title: 'The Vine and the Branches', passage: 'John 15:1-17', passageText: '"Abide in me, and I in you. As the branch cannot bear fruit by itself, unless it abides in the vine, neither can you, unless you abide in me."', reflection: 'Abiding is not striving — it is staying connected. What does it look like practically for you to abide in Christ this week?', aiPrompt: 'I\'m reading John 15:1-17, the vine and branches passage. Help me understand what "abiding" means, what it means to be pruned, and the connection between abiding and bearing fruit. What does fruitfulness look like in a believer\'s life?'),
      StudyDay(day: 18, title: 'The World\'s Hatred', passage: 'John 15:18-16:4', passageText: '"If the world hates you, know that it has hated me before it hated you."', reflection: 'Jesus prepared his disciples for rejection, not success. How do you respond when your faith costs you something?', aiPrompt: 'Help me understand John 15:18-16:4, where Jesus warns about the world\'s hatred. What did he mean by "the world"? Why does following Jesus sometimes lead to rejection, and how does this prepare us rather than discourage us?'),
      StudyDay(day: 19, title: 'Grief into Joy', passage: 'John 16:16-33', passageText: '"I have said these things to you, that in me you may have peace. In the world you will have tribulation. But take heart; I have overcome the world."', reflection: 'Jesus promised both tribulation and peace in the same breath. How do you hold those two realities together in your own life?', aiPrompt: 'I\'m studying John 16:16-33. Help me understand what Jesus meant about sorrow turning to joy, his promise of peace alongside tribulation, and what it means that he has "overcome the world."'),
      StudyDay(day: 20, title: 'Jesus Prays for Us', passage: 'John 17:1-26', passageText: '"I do not ask for these only, but also for those who will believe in me through their word."', reflection: 'Jesus prayed for you — specifically, by name in his heart — the night before he died. How does it change things to know that you were on his mind in his darkest hour?', aiPrompt: 'Help me understand John 17, the High Priestly Prayer. What was Jesus praying for? What does it mean that he prayed for those who would believe through the disciples\' word — including us today? What is the unity he prayed for?'),
      StudyDay(day: 21, title: 'The Arrest', passage: 'John 18:1-27', passageText: '"I told you that I am he. So, if you seek me, let these men go."', reflection: 'In the moment of his arrest, Jesus\'s concern was for his disciples\' safety. His love was active even in his suffering. What does that tell you about his love for you?', aiPrompt: 'I\'m reading John 18:1-27, Jesus\'s arrest and Peter\'s denial. Help me understand Jesus\'s response at his arrest, why he said "I am he," and the significance of Peter\'s denial — and what hope there is for us when we fail.'),
      StudyDay(day: 22, title: 'Before Pilate', passage: 'John 18:28-19:16', passageText: '"What is truth?" Pilate asked.', reflection: 'Pilate asked "what is truth?" while standing in front of the one who is Truth. Are there ways you are doing the same thing — asking questions while avoiding the answer?', aiPrompt: 'Help me understand the trial before Pilate in John 18:28-19:16. What was Pilate\'s dilemma? What did Jesus mean when he said his kingdom is "not of this world"? And what is the significance of Pilate\'s question "What is truth?"'),
      StudyDay(day: 23, title: 'The Crucifixion', passage: 'John 19:17-37', passageText: '"It is finished."', reflection: '"Tetelestai" — it is finished. In Greek this was a word stamped on a paid debt. What debt did Jesus pay that you could not?', aiPrompt: 'I\'m studying the crucifixion in John 19:17-37. Help me understand the Greek word "tetelestai" — "it is finished" — its full meaning and significance. What was finished? And what is the meaning of the blood and water that flowed from Jesus\'s side?'),
      StudyDay(day: 24, title: 'The Burial', passage: 'John 19:38-42', passageText: 'Joseph of Arimathea and Nicodemus came and took the body of Jesus.', reflection: 'Nicodemus came to Jesus at night in chapter 3 — afraid and in secret. Here he comes openly to honor Jesus in death. What changed him? What is changing you?', aiPrompt: 'Help me understand John 19:38-42. Who were Joseph of Arimathea and Nicodemus, and what was the significance of them claiming Jesus\'s body publicly? What does this moment tell us about how Jesus transforms people — even slowly, over time?'),
      StudyDay(day: 25, title: 'The Empty Tomb', passage: 'John 20:1-10', passageText: 'For as yet they did not understand the Scripture, that he must rise from the dead.', reflection: 'Even the disciples did not understand at first. Understanding the resurrection can take time. Where are you in your own understanding of it?', aiPrompt: 'I\'m reading John 20:1-10, the discovery of the empty tomb. Help me understand the details John includes — the linen cloths, the face cloth folded separately — and what they suggest about the resurrection. Why does John note that they "did not yet understand"?'),
      StudyDay(day: 26, title: 'Mary Magdalene', passage: 'John 20:11-18', passageText: 'Jesus said to her, "Mary." She turned and said to him in Aramaic, "Rabboni!" (which means Teacher).', reflection: 'Jesus called her by name and everything changed. He still calls people by name. Have you heard him calling yours?', aiPrompt: 'Help me understand John 20:11-18, where Jesus appears to Mary Magdalene. Why did she not recognize him at first? What is the significance of him calling her by name? And what did he mean when he said "do not cling to me"?'),
      StudyDay(day: 27, title: 'Peace Be With You', passage: 'John 20:19-23', passageText: '"Peace be with you. As the Father has sent me, even so I am sending you."', reflection: 'The disciples were hiding behind locked doors in fear. Jesus came through the walls to reach them. Is there a locked room in your heart he is trying to enter?', aiPrompt: 'I\'m studying John 20:19-23. Help me understand Jesus appearing to the disciples in the locked room. What was the significance of his words "Peace be with you"? What did it mean when he breathed on them and said "receive the Holy Spirit"?'),
      StudyDay(day: 28, title: 'Doubting Thomas', passage: 'John 20:24-31', passageText: '"Have you believed because you have seen me? Blessed are those who have not seen and yet have believed."', reflection: 'Thomas gets a bad reputation, but Jesus did not condemn his doubt — he met it. What doubts have you been afraid to bring to Jesus?', aiPrompt: 'Help me understand John 20:24-31. Why did Thomas doubt? How did Jesus respond to his doubt, and what does that tell us about how God handles our unbelief? What does the benediction "blessed are those who have not seen and yet have believed" mean for us today?'),
      StudyDay(day: 29, title: 'Breakfast on the Shore', passage: 'John 21:1-14', passageText: 'Jesus said to them, "Come and have breakfast."', reflection: 'After the resurrection, Jesus made breakfast. He is present in the ordinary moments. Where have you seen him in the everyday this week?', aiPrompt: 'I\'m reading John 21:1-14. Help me understand the significance of the disciples returning to fishing, the miraculous catch, and Jesus making breakfast on the shore. What was Jesus communicating through these very ordinary acts after such extraordinary events?'),
      StudyDay(day: 30, title: 'Do You Love Me?', passage: 'John 21:15-25', passageText: '"Simon, son of John, do you love me?" ... "Feed my sheep."', reflection: 'Jesus restored Peter with the same question three times — once for each denial. He is in the business of restoration. Is there something you need to be restored from today?', aiPrompt: 'Help me understand John 21:15-25, Jesus\'s restoration of Peter. Why did Jesus ask three times? What is the difference between the Greek words for love used — agape and phileo? And what does Peter\'s restoration tell us about how Jesus handles our failures?'),
    ],
  ),

  // ── 2. Psalms of Comfort ─────────────────────────────────────────────────
  BibleStudy(
    id: 'psalms_14',
    title: 'Psalms of Comfort',
    subtitle: '14 Days',
    description: 'When words fail, the Psalms speak. A two-week journey through Scripture\'s most honest and tender prayers for those carrying heavy hearts.',
    iconData: Icons.self_improvement,
    totalDays: 14,
    days: [
      StudyDay(day: 1, title: 'The Lord is My Shepherd', passage: 'Psalm 23', passageText: 'The Lord is my shepherd; I shall not want.', reflection: 'Every image in Psalm 23 is one of provision and protection. Which image speaks most to what you need right now?', aiPrompt: 'I\'m meditating on Psalm 23 today. Help me go deeper into each image — the shepherd, green pastures, still waters, the valley of the shadow of death, the table prepared before enemies. What did these mean in their original context and what do they mean for us today?'),
      StudyDay(day: 2, title: 'Out of the Depths', passage: 'Psalm 130', passageText: 'Out of the depths I cry to you, O Lord!', reflection: 'This psalm begins in the depths and ends in hope. What depths are you calling out from today?', aiPrompt: 'Help me understand Psalm 130 — a psalm of ascent that begins in despair and ends in hope. What does "out of the depths" mean? What is the significance of "waiting for the Lord" and the image of watchmen waiting for the morning?'),
      StudyDay(day: 3, title: 'God is Our Refuge', passage: 'Psalm 46', passageText: 'God is our refuge and strength, a very present help in trouble.', reflection: '"Be still, and know that I am God." What would it look like to truly be still today?', aiPrompt: 'I\'m studying Psalm 46. Help me understand the imagery of the earth giving way and mountains falling — what was the psalmist facing? And what does it mean that God is "a very present help in trouble" and that we should "be still"?'),
      StudyDay(day: 4, title: 'Why Are You Cast Down?', passage: 'Psalm 42-43', passageText: 'Why are you cast down, O my soul, and why are you in turmoil within me? Hope in God.', reflection: 'The psalmist talks to his own soul — challenging it to hope. What would you say to your own soul today?', aiPrompt: 'Help me understand Psalms 42-43 together. The psalmist is clearly in deep distress. How does he process his grief honestly while still choosing hope? What does the refrain "hope in God; for I shall again praise him" teach us about faith in dark seasons?'),
      StudyDay(day: 5, title: 'He Heals the Brokenhearted', passage: 'Psalm 147:1-11', passageText: 'He heals the brokenhearted and binds up their wounds.', reflection: 'God heals and God counts stars — both in the same psalm. What does it mean that the God of the universe is personally concerned with your broken heart?', aiPrompt: 'I\'m reading Psalm 147:1-11. Help me understand the connection between God healing the brokenhearted and God counting and naming the stars. What does this juxtaposition tell us about God\'s nature and his care for us?'),
      StudyDay(day: 6, title: 'A Fortress in the Storm', passage: 'Psalm 91', passageText: 'He who dwells in the shelter of the Most High will abide in the shadow of the Almighty.', reflection: 'This psalm lists many forms of danger — pestilence, snares, terror by night. Which fear does God\'s protection speak to most directly in your life?', aiPrompt: 'Help me understand Psalm 91. What does it mean to "dwell in the shelter of the Most High"? What are the different images of protection used, and how should we understand the promise of protection — does it mean nothing bad will ever happen?'),
      StudyDay(day: 7, title: 'Steadfast Love', passage: 'Psalm 136', passageText: 'Give thanks to the Lord, for he is good, for his steadfast love endures forever.', reflection: 'The Hebrew word "hesed" — steadfast love — appears 26 times in this psalm. It means covenant loyalty, faithful love that never quits. Have you experienced that kind of love?', aiPrompt: 'I\'m studying Psalm 136, where every verse ends with "his steadfast love endures forever." Help me understand the Hebrew word hesed and why it matters. What is the psalm rehearsing, and why is remembering God\'s past faithfulness so important for present trust?'),
      StudyDay(day: 8, title: 'Create in Me a Clean Heart', passage: 'Psalm 51', passageText: 'Create in me a clean heart, O God, and renew a right spirit within me.', reflection: 'David wrote this after his greatest failure. He did not hide from God — he ran to him. What failures are you still hiding?', aiPrompt: 'Help me understand Psalm 51, David\'s psalm of repentance after his sin with Bathsheba. What does he ask for? What is the difference between the sacrifices God doesn\'t want and the "broken and contrite heart" he does? And what hope does this psalm offer for people who have failed badly?'),
      StudyDay(day: 9, title: 'My Help Comes from the Lord', passage: 'Psalm 121', passageText: 'I lift up my eyes to the hills. From where does my help come? My help comes from the Lord.', reflection: 'The psalmist lifted his eyes from his circumstances to the Creator of those circumstances. What would change if you did the same today?', aiPrompt: 'I\'m reading Psalm 121. Help me understand the significance of "lifting eyes to the hills" in its ancient context, and the beautiful repetition of God as keeper and guardian. What does it mean that God neither slumbers nor sleeps?'),
      StudyDay(day: 10, title: 'Taste and See', passage: 'Psalm 34', passageText: 'Oh, taste and see that the Lord is good! Blessed is the man who takes refuge in him!', reflection: 'Faith is described here as something you taste — personal, experiential, not just intellectual. When did you last personally taste God\'s goodness?', aiPrompt: 'Help me understand Psalm 34. What is the context — David wrote this in a desperate, humiliating situation. How does joy come through in this psalm despite that? And what does "taste and see that the Lord is good" invite us to do?'),
      StudyDay(day: 11, title: 'The Lord is Near', passage: 'Psalm 34:18, Psalm 145:18', passageText: 'The Lord is near to the brokenhearted and saves the crushed in spirit.', reflection: 'God\'s nearness is specifically promised to the brokenhearted — not to the strong. Have you ever felt God closest in your hardest moments?', aiPrompt: 'I want to meditate on the theme of God\'s nearness in Psalm 34:18 and Psalm 145:18. Help me understand what it means that God is "near to the brokenhearted" — is this a promise of feeling his presence, or something deeper? How do we experience this practically?'),
      StudyDay(day: 12, title: 'Weeping May Last', passage: 'Psalm 30', passageText: 'Weeping may tarry for the night, but joy comes with the morning.', reflection: 'The psalm does not say pain is short — it says it is not permanent. What "night" are you in, and what does it mean to trust that morning is coming?', aiPrompt: 'Help me understand Psalm 30. What was David\'s situation? What does the journey from mourning to dancing look like in this psalm? And how should we honestly hold onto "joy comes in the morning" when the night feels very long?'),
      StudyDay(day: 13, title: 'Cast Your Burden', passage: 'Psalm 55:22, Psalm 62', passageText: 'Cast your burden on the Lord, and he will sustain you; he will never permit the righteous to be moved.', reflection: 'Casting a burden requires letting go of it. What burden are you still carrying that you keep taking back from God?', aiPrompt: 'I\'m meditating on Psalm 55:22 and Psalm 62 — the theme of casting burdens and waiting on God. Help me understand what "casting" really means, and how Psalm 62\'s language of God as rock, fortress, and refuge speaks to someone who is exhausted and struggling.'),
      StudyDay(day: 14, title: 'His Mercies Are New', passage: 'Lamentations 3:19-33', passageText: 'The steadfast love of the Lord never ceases; his mercies never come to an end; they are new every morning; great is your faithfulness.', reflection: 'This passage comes from a book written in the rubble of Jerusalem\'s destruction. Yet in the middle of devastation, the writer chose to remember God\'s faithfulness. What choice will you make today?', aiPrompt: 'Help me understand Lamentations 3:19-33. This is one of the most hopeful passages in Scripture — but it comes from the most grief-filled book in the Bible. What makes this declaration of God\'s faithfulness so powerful given its context? And what does "great is your faithfulness" mean when circumstances say otherwise?'),
    ],
  ),

  // ── 3. Romans: The Gospel Unpacked ──────────────────────────────────────
  BibleStudy(
    id: 'romans_30',
    title: 'Romans: The Gospel',
    subtitle: '30 Days',
    description: 'The most systematic and powerful presentation of the gospel ever written. Romans will challenge your mind and transform your understanding of grace.',
    iconData: Icons.bolt,
    totalDays: 30,
    days: [
      StudyDay(day: 1, title: 'The Power of the Gospel', passage: 'Romans 1:1-17', passageText: 'For I am not ashamed of the gospel, for it is the power of God for salvation to everyone who believes.', reflection: 'Paul says he is "not ashamed" of the gospel — implying it could have been shameful in Roman culture. Are there places where you are tempted to be ashamed of your faith?', aiPrompt: 'I\'m starting Romans today with Romans 1:1-17. Help me understand Paul\'s introduction — who he says he is, what the gospel is, and the famous statement "I am not ashamed of the gospel." What does he mean by "the righteousness of God is revealed from faith for faith"?'),
      StudyDay(day: 2, title: 'The Human Problem', passage: 'Romans 1:18-32', passageText: 'For the wrath of God is revealed from heaven against all ungodliness and unrighteousness of men.', reflection: 'Paul\'s diagnosis is uncomfortable — humanity suppresses truth and exchanges the Creator for creation. Where do you see this in culture today? In yourself?', aiPrompt: 'Help me understand Romans 1:18-32. What does Paul mean by the "wrath of God"? What is the progression he describes — suppressing truth, exchanging God\'s glory, being "given over"? And how should we read this passage with both honesty and compassion?'),
      StudyDay(day: 3, title: 'No One is Righteous', passage: 'Romans 3:9-20', passageText: 'None is righteous, no, not one.', reflection: 'Paul quotes the Psalms to show this is not new news — humanity has always been in need of rescue. Does acknowledging your own need feel liberating or threatening?', aiPrompt: 'I\'m reading Romans 3:9-20. Help me understand why Paul quotes so many Old Testament passages here. What is he trying to establish? And why is the conclusion "no one is righteous" actually the foundation of good news rather than despair?'),
      StudyDay(day: 4, title: 'Justified by Faith', passage: 'Romans 3:21-31', passageText: 'For we hold that one is justified by faith apart from works of the law.', reflection: 'Justification means being declared righteous — not becoming righteous, but being declared so. How does the difference between earning and receiving change how you approach God?', aiPrompt: 'Help me understand Romans 3:21-31 — the heart of Paul\'s gospel. What does "justified" mean in Greek legal terms? What does "propitiation" mean in Romans 3:25? And why does Paul insist that faith excludes boasting?'),
      StudyDay(day: 5, title: 'Abraham\'s Faith', passage: 'Romans 4:1-25', passageText: 'Abraham believed God, and it was counted to him as righteousness.', reflection: 'Abraham was declared righteous before circumcision — before any religious act. What does this tell you about the basis of your standing before God?', aiPrompt: 'I\'m studying Romans 4. Help me understand why Paul uses Abraham as his example of justification by faith. What is significant about the timing — Abraham being declared righteous before circumcision? And what does it mean that his faith was "counted as righteousness"?'),
      StudyDay(day: 6, title: 'Peace with God', passage: 'Romans 5:1-11', passageText: 'Therefore, since we have been justified by faith, we have peace with God through our Lord Jesus Christ.', reflection: 'Peace with God is not a feeling — it is a legal status. The war is over. How does knowing God is not against you change how you live?', aiPrompt: 'Help me understand Romans 5:1-11. What does "peace with God" mean — is it a feeling or something more? What is the progression: tribulation → endurance → character → hope? And what does "God shows his love for us in that while we were still sinners, Christ died for us" mean for our sense of worth?'),
      StudyDay(day: 7, title: 'Death Through Adam, Life Through Christ', passage: 'Romans 5:12-21', passageText: 'For as by the one man\'s disobedience the many were made sinners, so by the one man\'s obedience the many will be made righteous.', reflection: 'Two men — two different outcomes for all of humanity. Which man\'s story are you living in today?', aiPrompt: 'I\'m reading Romans 5:12-21. Help me understand Paul\'s Adam-Christ comparison. What does it mean that sin entered through one man? How does Christ\'s obedience reverse Adam\'s disobedience? And what does "much more" suggest about the extent of grace compared to sin?'),
      StudyDay(day: 8, title: 'Dead to Sin', passage: 'Romans 6:1-14', passageText: 'So you also must consider yourselves dead to sin and alive to God in Christ Jesus.', reflection: '"Consider yourselves dead to sin" — this is something we do with our minds, not a feeling. What would change in your daily life if you truly believed sin no longer had authority over you?', aiPrompt: 'Help me understand Romans 6:1-14. What does it mean to be "baptized into his death"? What does Paul mean when he says we should "consider ourselves dead to sin"? Is this something that happens automatically or something we must actively do?'),
      StudyDay(day: 9, title: 'Slaves to Righteousness', passage: 'Romans 6:15-23', passageText: 'For the wages of sin is death, but the free gift of God is eternal life in Christ Jesus our Lord.', reflection: 'Paul says everyone is a slave to something — sin or righteousness. There is no neutrality. What are you most enslaved to right now?', aiPrompt: 'I\'m studying Romans 6:15-23. Help me understand Paul\'s slavery metaphor. Why does he say we are either slaves to sin or slaves to righteousness — is there no middle ground? And what is the contrast between "wages" and "free gift" in Romans 6:23?'),
      StudyDay(day: 10, title: 'The Struggle is Real', passage: 'Romans 7:14-25', passageText: 'For I do not do what I want, but I do the very thing I hate.', reflection: 'Paul describes the internal war every believer knows. You are not alone in your struggle. How does knowing even Paul fought this battle change how you see your own?', aiPrompt: 'Help me understand Romans 7:14-25 — Paul\'s famous "I do not do what I want" passage. Is Paul describing his pre-Christian or post-Christian experience? Why does this matter? And what is the resolution he points to in verse 25?'),
      StudyDay(day: 11, title: 'No Condemnation', passage: 'Romans 8:1-11', passageText: 'There is therefore now no condemnation for those who are in Christ Jesus.', reflection: '"No condemnation" — not "less condemnation" or "condemnation when you deserve it." This is total. How would your relationship with God change if you fully believed this?', aiPrompt: 'I\'m reading Romans 8:1-11, one of the most important passages in the New Testament. Help me understand what "no condemnation" means legally and personally. What is the "law of the Spirit of life"? And how does the Spirit\'s indwelling change everything about how we live?'),
      StudyDay(day: 12, title: 'Sons and Daughters of God', passage: 'Romans 8:12-17', passageText: 'You did not receive the spirit of slavery to fall back into fear, but you have received the Spirit of adoption as sons, by whom we cry, "Abba! Father!"', reflection: '"Abba" is the intimate Aramaic word for Father — closer to "Daddy" than "Sir." Is that how you approach God? What makes it hard?', aiPrompt: 'Help me understand Romans 8:12-17. What is the significance of adoption in the Roman world — what rights did adopted children have? And what does "Abba, Father" tell us about the relationship the Spirit creates between us and God?'),
      StudyDay(day: 13, title: 'Future Glory', passage: 'Romans 8:18-27', passageText: 'For I consider that the sufferings of this present time are not worth comparing with the glory that is to be revealed to us.', reflection: 'Paul wrote this from a life of shipwrecks, beatings, and imprisonment. He still called present suffering "not worth comparing." What would it take for you to hold suffering that loosely?', aiPrompt: 'I\'m studying Romans 8:18-27. Help me understand Paul\'s view of present suffering compared to future glory. What does it mean that creation is "groaning"? And what does the Spirit\'s intercession with "groanings too deep for words" tell us about prayer in our weakness?'),
      StudyDay(day: 14, title: 'All Things Work Together', passage: 'Romans 8:28-30', passageText: 'And we know that for those who love God all things work together for good, for those who are called according to his purpose.', reflection: 'This is one of the most quoted and most misunderstood verses in the Bible. What does "all things work together for good" actually promise — and what does it not promise?', aiPrompt: 'Help me understand Romans 8:28-30. What does "all things work together for good" actually mean? What is the "good" Paul is referring to — verse 29 gives a clue. Who are "those who love God" and "those called according to his purpose"? And how should we hold this promise in genuine suffering?'),
      StudyDay(day: 15, title: 'More Than Conquerors', passage: 'Romans 8:31-39', passageText: 'For I am sure that neither death nor life, nor angels nor rulers, nor things present nor things to come, nor powers, nor height nor depth, nor anything else in all creation, will be able to separate us from the love of God in Christ Jesus our Lord.', reflection: 'Paul lists every possible enemy and declares none of them can separate you from God\'s love. Which of those "enemies" feels most threatening in your life right now?', aiPrompt: 'I\'m meditating on Romans 8:31-39, one of the greatest passages in Scripture. Help me understand the logic Paul builds — "If God is for us, who can be against us?" What does "more than conquerors" mean? And why does Paul end with such a comprehensive list of things that cannot separate us from God\'s love?'),
      StudyDay(day: 16, title: 'God\'s Sovereign Choice', passage: 'Romans 9:1-29', passageText: 'So then it depends not on human will or exertion, but on God, who has mercy.', reflection: 'Romans 9 is one of the hardest chapters in the Bible. Paul\'s main point is that God\'s word has not failed. How do you hold the tension between God\'s sovereignty and human responsibility?', aiPrompt: 'Help me understand Romans 9:1-29. This is one of the most debated chapters in Scripture. What is Paul\'s main argument? How does he use Old Testament examples? And how should Christians who disagree about election approach this passage with humility?'),
      StudyDay(day: 17, title: 'Salvation for All', passage: 'Romans 10:1-17', passageText: 'For everyone who calls on the name of the Lord will be saved.', reflection: '"Everyone" — Jew and Gentile, religious and secular, near and far. Is there someone in your life you have written off as beyond reach?', aiPrompt: 'I\'m studying Romans 10:1-17. Help me understand the contrast between "righteousness based on the law" and "righteousness based on faith." What does the famous passage about confessing and believing mean? And what is the significance of "faith comes from hearing"?'),
      StudyDay(day: 18, title: 'The Remnant', passage: 'Romans 11:1-24', passageText: 'So too at the present time there is a remnant, chosen by grace.', reflection: 'God always preserves a remnant — even in Israel\'s darkest seasons. Is there a remnant of faith in you that has survived your hardest seasons?', aiPrompt: 'Help me understand Romans 11:1-24. What is Paul saying about Israel and the Gentiles? What is the "remnant chosen by grace"? And what does the olive tree metaphor teach about the relationship between Israel and the Church?'),
      StudyDay(day: 19, title: 'The Depth of God\'s Wisdom', passage: 'Romans 11:25-36', passageText: 'Oh, the depth of the riches and wisdom and knowledge of God! How unsearchable are his judgments and how inscrutable his ways!', reflection: 'Paul ends this difficult section not with a systematic conclusion but with worship. When was the last time the complexity of God drove you to wonder rather than frustration?', aiPrompt: 'I\'m reading Romans 11:25-36, Paul\'s great doxology. Help me understand what he is celebrating. What does "all Israel will be saved" mean? And why does Paul break into worship at this point — what about God\'s plan moves him to this response?'),
      StudyDay(day: 20, title: 'Living Sacrifices', passage: 'Romans 12:1-2', passageText: 'I appeal to you therefore, brothers, by the mercies of God, to present your bodies as a living sacrifice, holy and acceptable to God, which is your spiritual worship.', reflection: 'The "therefore" connects to everything in Romans 1-11. Because of all that grace, present yourself. What would it look like to present your body — your actual daily life — as worship?', aiPrompt: 'Help me understand Romans 12:1-2. What is the "therefore" connecting back to? What does "living sacrifice" mean — and why is it harder than being a dead sacrifice? What does "renewing of your mind" look like practically, and what is it contrasted with?'),
      StudyDay(day: 21, title: 'One Body, Many Parts', passage: 'Romans 12:3-8', passageText: 'For as in one body we have many members, and the members do not all have the same function, so we, though many, are one body in Christ.', reflection: 'Every gift matters. No gift is more important than another. What gift has God placed in you that you have been hesitant to use?', aiPrompt: 'I\'m studying Romans 12:3-8. Help me understand Paul\'s teaching on gifts and the body of Christ. What does "sober judgment" about ourselves mean? And how does the community of believers fit together in a way that requires everyone?'),
      StudyDay(day: 22, title: 'Genuine Love', passage: 'Romans 12:9-21', passageText: 'Let love be genuine. Abhor what is evil; hold fast to what is good.', reflection: '"Genuine" love is the opposite of performance. Where in your life are you performing love rather than genuinely practicing it?', aiPrompt: 'Help me understand Romans 12:9-21. Paul gives a rapid series of commands about love. Help me understand what "genuine love" looks like in practice — especially the harder commands like "bless those who persecute you" and "overcome evil with good."'),
      StudyDay(day: 23, title: 'Governing Authorities', passage: 'Romans 13:1-7', passageText: 'Let every person be subject to the governing authorities. For there is no authority except from God.', reflection: 'Paul wrote this under the Roman Empire — not a Christian government. What does submission to authority look like when the authority is imperfect or even unjust?', aiPrompt: 'I\'m studying Romans 13:1-7. Help me understand Paul\'s teaching on governing authorities. Why did he write this? What are the limits of this submission — are there times Christians should not obey? How does the church historically balance this passage with resistance to injustice?'),
      StudyDay(day: 24, title: 'The Armor of Light', passage: 'Romans 13:8-14', passageText: 'Put on the Lord Jesus Christ, and make no provision for the flesh, to gratify its desires.', reflection: '"Put on the Lord Jesus Christ" — as if clothing yourself. What would it look like to "dress" in Christ today before you face the world?', aiPrompt: 'Help me understand Romans 13:8-14. What does "the night is far gone; the day is at hand" mean in Paul\'s eschatological thinking? And what does "put on the Lord Jesus Christ" mean practically — how do we do this?'),
      StudyDay(day: 25, title: 'The Strong and the Weak', passage: 'Romans 14:1-23', passageText: 'Why do you pass judgment on your brother? Or you, why do you despise your brother? For we will all stand before the judgment seat of God.', reflection: 'Paul calls the church to make room for different convictions on secondary matters. Where do you tend to be the "strong" person who judges, and where do you tend to be the "weak" person who stumbles?', aiPrompt: 'I\'m reading Romans 14. Help me understand the conflict Paul is addressing — what were the "strong" and "weak" disagreeing about? What principles does Paul give for navigating disagreements about non-essential matters? And how does this apply to church conflicts today?'),
      StudyDay(day: 26, title: 'Welcome One Another', passage: 'Romans 15:1-13', passageText: 'Therefore welcome one another as Christ has welcomed you, for the glory of God.', reflection: 'Christ welcomed you while you were still a sinner — before you changed. Who in your life needs to be welcomed before they change?', aiPrompt: 'Help me understand Romans 15:1-13. What does it mean for the strong to "bear with the failings of the weak"? And what is the connection between Christ\'s welcome of us and our welcome of one another? What does verse 13 tell us about the God of hope?'),
      StudyDay(day: 27, title: 'Paul\'s Mission', passage: 'Romans 15:14-33', passageText: 'I have made it my ambition to preach the gospel, not where Christ has already been named.', reflection: 'Paul\'s ambition was entirely shaped by the gospel. What ambition is shaping your life right now?', aiPrompt: 'I\'m studying Romans 15:14-33. Help me understand Paul\'s missionary strategy and his ambitious plan to reach Spain. What drove him? And what can we learn from his request for prayer — even the great apostle Paul needed the church to pray for him?'),
      StudyDay(day: 28, title: 'Greet One Another', passage: 'Romans 16:1-16', passageText: 'Greet Prisca and Aquila, my fellow workers in Christ Jesus, who risked their necks for my life.', reflection: 'Paul names 26 people by name in this chapter. Faith is not a solo journey. Who are the people who have "risked their necks" for your faith?', aiPrompt: 'Help me understand Romans 16:1-16. Why does Paul spend so much time greeting individuals? What does the variety of people he mentions — women leaders, slaves, Gentiles, Jews — tell us about the early church? And what does this chapter say about the importance of community?'),
      StudyDay(day: 29, title: 'Watch Out for Divisions', passage: 'Romans 16:17-20', passageText: 'For such persons do not serve our Lord Christ, but their own appetites, and by smooth talk and flattery they deceive the hearts of the naive.', reflection: 'Paul warns about those who cause division — even in a loving letter full of greetings. What does healthy discernment look like without becoming suspicious of everyone?', aiPrompt: 'I\'m reading Romans 16:17-20. Help me understand Paul\'s warning about those who cause divisions and create obstacles. Who was he concerned about? And what does "wise as to what is good, innocent as to what is evil" look like practically?'),
      StudyDay(day: 30, title: 'To the Only Wise God', passage: 'Romans 16:25-27', passageText: 'To the only wise God be glory forevermore through Jesus Christ! Amen.', reflection: 'Romans ends not with a summary but with praise. After 16 chapters of theology, Paul\'s response is worship. What is your response after 30 days in this letter?', aiPrompt: 'Help me understand Romans 16:25-27, Paul\'s closing doxology. What is the "mystery that was kept secret for long ages but has now been disclosed"? And why does Paul end this profound theological letter with worship — what does that tell us about the relationship between theology and doxology?'),
    ],
  ),

  // ── 4. New Believer Foundations ─────────────────────────────────────────
  BibleStudy(
    id: 'foundations_21',
    title: 'Faith Foundations',
    subtitle: '21 Days',
    description: 'The essential truths of the Christian faith — explained clearly, explored personally. Perfect for anyone starting or restarting their faith journey.',
    iconData: Icons.eco,
    totalDays: 21,
    days: [
      StudyDay(day: 1, title: 'Who is God?', passage: 'Psalm 139:1-18', passageText: 'O Lord, you have searched me and known me!', reflection: 'God knows everything about you — and still pursues you. Does that feel comforting or uncomfortable? Why?', aiPrompt: 'I\'m just starting to explore my faith. Can you help me understand who God is — using Psalm 139 as a starting point? What does it mean that God searches us and knows us, and what kind of God would do that?'),
      StudyDay(day: 2, title: 'Why Does Evil Exist?', passage: 'Genesis 3:1-24', passageText: 'The Lord God called to the man and said to him, "Where are you?"', reflection: 'God\'s first question after the fall was "where are you?" — not in anger, but in pursuit. What does that tell you about God\'s character?', aiPrompt: 'Help me understand Genesis 3 — the fall of humanity. Why did God allow this? What does the entrance of sin explain about the world we live in? And what is the significance of God asking "where are you?" — his first words after the fall?'),
      StudyDay(day: 3, title: 'Who is Jesus?', passage: 'John 1:1-14, Colossians 1:15-20', passageText: 'He is the image of the invisible God, the firstborn of all creation.', reflection: 'Jesus is described as the visible image of an invisible God. What does Jesus show you about what God is like?', aiPrompt: 'I want to understand who Jesus really is. Help me explore John 1:1-14 and Colossians 1:15-20 together. What do these passages claim about Jesus? What does it mean that he is "the image of the invisible God" and "the Word became flesh"?'),
      StudyDay(day: 4, title: 'Why Did Jesus Die?', passage: 'Isaiah 53:1-12, Romans 5:6-8', passageText: 'But God shows his love for us in that while we were still sinners, Christ died for us.', reflection: 'Jesus died for you while you were still far from him — not after you cleaned up. How does that change the way you see his love?', aiPrompt: 'Help me understand why Jesus had to die. Using Isaiah 53 and Romans 5:6-8, help me understand the concept of substitution — what was accomplished at the cross, and why was it necessary?'),
      StudyDay(day: 5, title: 'Did Jesus Rise?', passage: '1 Corinthians 15:1-22', passageText: 'If Christ has not been raised, your faith is futile. But in fact Christ has been raised from the dead.', reflection: 'Paul says if the resurrection is not true, Christianity is worthless. But if it is true, everything changes. What does the resurrection mean to you personally?', aiPrompt: 'I want to understand the resurrection. Help me explore 1 Corinthians 15:1-22 — why does Paul say the resurrection is the foundation of everything? What evidence does he point to? And what difference does the resurrection make practically?'),
      StudyDay(day: 6, title: 'How Am I Made Right with God?', passage: 'Ephesians 2:1-10', passageText: 'For by grace you have been saved through faith. And this is not your own doing; it is the gift of God.', reflection: 'Salvation is described as a gift — not a reward, not a wage. Have you ever received it as such?', aiPrompt: 'Help me understand Ephesians 2:1-10. What does it mean to be "saved by grace through faith"? What is grace? What is faith? And why does Paul emphasize that it is "not your own doing"?'),
      StudyDay(day: 7, title: 'What is the Holy Spirit?', passage: 'John 14:15-27, Acts 2:1-13', passageText: 'But the Helper, the Holy Spirit, whom the Father will send in my name, he will teach you all things.', reflection: 'The Holy Spirit is described as a Helper, Counselor, and Teacher — present with every believer. Have you experienced his presence? How?', aiPrompt: 'I want to understand the Holy Spirit. Help me explore John 14:15-27 and Acts 2:1-13. Who is the Holy Spirit? What does he do? And how do we experience his presence and work in daily life?'),
      StudyDay(day: 8, title: 'What is Prayer?', passage: 'Matthew 6:5-13, Philippians 4:6-7', passageText: 'Do not be anxious about anything, but in everything by prayer and supplication with thanksgiving let your requests be made known to God.', reflection: 'Prayer is described here not as a religious duty but as the antidote to anxiety. What would change in your daily life if you prayed instead of worried?', aiPrompt: 'Help me understand what prayer is and how to do it. Using Matthew 6:5-13 (the Lord\'s Prayer) and Philippians 4:6-7, explain what Jesus taught about prayer, what the Lord\'s Prayer covers, and how prayer relates to peace and anxiety.'),
      StudyDay(day: 9, title: 'Why Read the Bible?', passage: '2 Timothy 3:14-17, Psalm 119:105', passageText: 'Your word is a lamp to my feet and a light to my path.', reflection: 'Scripture is described as useful for teaching, rebuking, correcting, and training — four different functions. Which of those do you most need right now?', aiPrompt: 'Help me understand why the Bible matters and how to read it. Using 2 Timothy 3:14-17 and Psalm 119:105, explain what Scripture is, what it does, and practical advice for someone who wants to start reading the Bible regularly.'),
      StudyDay(day: 10, title: 'Why Church?', passage: 'Hebrews 10:24-25, Acts 2:42-47', passageText: 'And they devoted themselves to the apostles\' teaching and the fellowship, to the breaking of bread and the prayers.', reflection: 'The early church was marked by devotion — to teaching, fellowship, breaking bread, and prayer. Which of those four is most missing in your life?', aiPrompt: 'Help me understand why the local church matters. Using Hebrews 10:24-25 and Acts 2:42-47, explain what the early church looked like, what "not neglecting to meet together" means, and why community is essential to faith — not optional.'),
      StudyDay(day: 11, title: 'What About Doubt?', passage: 'John 20:24-29, Mark 9:24', passageText: '"Lord, I believe; help my unbelief!"', reflection: 'Mark 9:24 may be the most honest prayer in the Bible. Is it yours?', aiPrompt: 'I struggle with doubt and I want to understand if that\'s okay. Help me explore John 20:24-29 (doubting Thomas) and Mark 9:24 (the father who said "I believe, help my unbelief"). What do these passages say about how Jesus responds to honest doubt?'),
      StudyDay(day: 12, title: 'Forgiveness', passage: 'Psalm 103:8-14, 1 John 1:9', passageText: 'As far as the east is from the west, so far does he remove our transgressions from us.', reflection: '"As far as the east is from the west" — that distance is infinite, because east and west never meet. Have you let God\'s forgiveness travel that far from you?', aiPrompt: 'Help me understand forgiveness — both receiving it from God and extending it to others. Using Psalm 103:8-14 and 1 John 1:9, explain what forgiveness means, how complete it is, and what "confessing our sins" looks like in practice.'),
      StudyDay(day: 13, title: 'Identity in Christ', passage: '2 Corinthians 5:17, Galatians 2:20', passageText: 'Therefore, if anyone is in Christ, he is a new creation. The old has passed away; behold, the new has come.', reflection: 'Your identity in Christ is not something you earn — it is something you receive and then live into. What old identity do you need to let pass away?', aiPrompt: 'Help me understand what it means to have an identity in Christ. Using 2 Corinthians 5:17 and Galatians 2:20, explain what "new creation" means, what "I have been crucified with Christ" means, and how our identity changes when we follow Jesus.'),
      StudyDay(day: 14, title: 'Temptation and Sin', passage: '1 Corinthians 10:13, James 1:12-15', passageText: 'God is faithful, and he will not let you be tempted beyond your ability, but with the temptation he will also provide the way of escape.', reflection: 'God always provides a way of escape — but we have to look for it. In your most common area of temptation, what might that way of escape look like?', aiPrompt: 'Help me understand temptation and sin from a biblical perspective. Using 1 Corinthians 10:13 and James 1:12-15, explain the difference between temptation and sin, what the "way of escape" means, and how the process of temptation works according to James.'),
      StudyDay(day: 15, title: 'The Fruit of the Spirit', passage: 'Galatians 5:16-26', passageText: 'But the fruit of the Spirit is love, joy, peace, patience, kindness, goodness, faithfulness, gentleness, self-control.', reflection: 'Fruit grows — it is not manufactured. Which fruit of the Spirit do you most need to grow in? What conditions help fruit grow?', aiPrompt: 'Help me understand Galatians 5:16-26 and the fruit of the Spirit. What is the difference between the "works of the flesh" and the "fruit of the Spirit"? Why is it called "fruit" — what does that metaphor teach us about how these qualities develop?'),
      StudyDay(day: 16, title: 'Serving Others', passage: 'Mark 10:42-45, Philippians 2:3-8', passageText: 'For even the Son of Man came not to be served but to serve, and to give his life as a ransom for many.', reflection: 'Jesus defined greatness as service. How is that different from the world\'s definition of greatness? Which definition is shaping your ambitions?', aiPrompt: 'Help me understand the biblical call to serve others. Using Mark 10:42-45 and Philippians 2:3-8, explain what Jesus taught about servant leadership, what "consider others more significant than yourselves" means, and how the incarnation models humility.'),
      StudyDay(day: 17, title: 'Generosity', passage: '2 Corinthians 9:6-15, Luke 21:1-4', passageText: 'Each one must give as he has decided in his heart, not reluctantly or under compulsion, for God loves a cheerful giver.', reflection: 'The widow gave everything she had — not out of abundance but sacrifice. What does cheerful generosity look like for you in your current season?', aiPrompt: 'Help me understand what the Bible teaches about generosity and giving. Using 2 Corinthians 9:6-15 and Luke 21:1-4 (the widow\'s offering), explain what motivates biblical generosity, what "cheerful giving" means, and how we think about money as followers of Jesus.'),
      StudyDay(day: 18, title: 'Suffering and Faith', passage: 'Romans 8:18-28, James 1:2-4', passageText: 'Count it all joy, my brothers, when you meet trials of various kinds.', reflection: 'James does not say "if" you meet trials — he says "when." Suffering is expected, not exceptional. How does knowing that change how you face hard times?', aiPrompt: 'Help me understand what the Bible says about suffering. Using Romans 8:18-28 and James 1:2-4, explain why Christians still suffer, what "counting it all joy" means (and doesn\'t mean), and what God is doing in seasons of trial.'),
      StudyDay(day: 19, title: 'Love Your Neighbor', passage: 'Luke 10:25-37, Matthew 22:36-40', passageText: '"You shall love the Lord your God with all your heart and with all your soul and with all your mind. And a second is like it: You shall love your neighbor as yourself."', reflection: 'The Good Samaritan crossed every social barrier to help someone. Who is the "neighbor" in your life that you have been crossing to the other side of the road to avoid?', aiPrompt: 'Help me understand the Great Commandment and the parable of the Good Samaritan in Luke 10:25-37. Who is my neighbor? What does loving them look like in practice? And why did Jesus tell this particular story in response to that question?'),
      StudyDay(day: 20, title: 'Heaven and Eternal Life', passage: 'Revelation 21:1-7, John 14:1-3', passageText: '"He will wipe away every tear from their eyes, and death shall be no more, neither shall there be mourning, nor crying, nor pain anymore."', reflection: 'Heaven is described not as floating on clouds but as a renewed creation — physical, real, and beautiful. Does that change how you think about eternity?', aiPrompt: 'Help me understand what the Bible teaches about heaven and eternal life. Using Revelation 21:1-7 and John 14:1-3, explain what the "new heaven and new earth" means, what Jesus meant by "my Father\'s house," and what we can actually know about life after death.'),
      StudyDay(day: 21, title: 'Go and Make Disciples', passage: 'Matthew 28:18-20, Acts 1:8', passageText: '"Go therefore and make disciples of all nations, baptizing them in the name of the Father and of the Son and of the Holy Spirit."', reflection: 'The Great Commission is not just for missionaries — it is for every follower of Jesus. Who in your life needs to hear what you have found?', aiPrompt: 'Help me understand the Great Commission in Matthew 28:18-20 and Acts 1:8. What does "make disciples" mean — is it different from "making converts"? What does it look like for an ordinary person in ordinary life to live out this commission? And what does the promise "I am with you always" mean for us today?'),
    ],
  ),
];